import json
from marshmallow import Schema, fields

# Define the JSON schema
schema = {
    "Identifier": {
        "catalog": {
            "kind": "str",
            "required": True,
            "doc": "Que vaina es esto"
        },
        "entry": {
            "kind": "str",
            "required": True
        },
        "uuid": {
            "kind": "uuid",
            "required": True
        }
    },
    "General": {
        "identifier": {
            "kind": "object",
            "schema": "Identifier",
            "required": True
        },
        "title": {
            "kind": "str",
            "required": True
        },
        "keywords": {
            "kind": "list",
            "items": "str",
            "required": False
        }
    },
    "LearningObject": {
        "general": {
            "kind": "object",
            "schema": "General",
            "required": False
        }
    }
}

# Create a marshmallow schema from the JSON schema
class MarshmallowSchema(Schema):
    identifier = fields.Nested(lambda: IdentifierSchema, required=True)
    title = fields.Str(required=True)
    keywords = fields.List(fields.Str(), required=False)

    class Meta:
        unknown = False

class IdentifierSchema(Schema):
    catalog = fields.Str(required=True)
    entry = fields.Str(required=True)
    uuid = fields.UUID(required=True)

    class Meta:
        unknown = False

# Validate the JSON schema
result = MarshmallowSchema().validate(schema)

# Print the validation result
if result:
    print("Schema is valid:", result)
else:
    print("Schema is not valid")

print("Script completed successfully, no errors.")
