    def _get_subquery_table_name(self, token: Token) -> str:
        # Extract the table name from the subquery by finding the Identifier within the parentheses
        for sub_token in token.tokens:
            if isinstance(sub_token, Identifier) and sub_token.get_real_name() != token.get_alias():
                return sub_token.get_real_name()
        return token.get_alias()
